package courier;

import com.sun.net.httpserver.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.io.*;

public final class Server {
    private record Session(Map<String,Object> user,long expires){}
    private static final Map<String,Session> sessions=new ConcurrentHashMap<>();
    private static void respond(HttpExchange x,int code,Object data)throws IOException {byte[]b=Json.stringify(data).getBytes(java.nio.charset.StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.sendResponseHeaders(code,b.length);x.getResponseBody().write(b);x.close();}
    private static Map<String,Object> user(HttpExchange x){String cookies=Objects.toString(x.getRequestHeaders().getFirst("Cookie"),"");for(String c:cookies.split(";")){if(c.trim().startsWith("session=")){String token=c.trim().substring(8);Session s=sessions.get(token);if(s!=null&&s.expires()>System.currentTimeMillis())return s.user();sessions.remove(token);}}return null;}
    @SuppressWarnings("unchecked") private static Map<String,Object> body(HttpExchange x)throws IOException{byte[]b=x.getRequestBody().readNBytes(65537);if(b.length>65536)throw new Domain.ValidationException("Request too large.");Object o=Json.parse(new String(b,java.nio.charset.StandardCharsets.UTF_8));if(!(o instanceof Map))throw new Domain.ValidationException("JSON object required.");return (Map<String,Object>)o;}
    public static void main(String[]args)throws Exception{
        int port=args.length>0?Integer.parseInt(args[0]):Integer.parseInt(Config.get("PORT","8080"));
        Store store=new Store(new MySQLPersistence(Config.mysqlUrl(),Config.mysqlUser(),Config.mysqlPassword(),Config.database()),Path.of(Config.get("LEGACY_DATA_FILE","data/records.json")));
        HttpServer server=HttpServer.create(new InetSocketAddress(Config.get("HOST","127.0.0.1"),port),0);
        String secure=Boolean.parseBoolean(Config.get("COOKIE_SECURE","false"))?"; Secure":"";
        Set<String> origins=new HashSet<>(List.of("http://127.0.0.1:"+port,"http://localhost:"+port));
        for(String allowed:Config.get("ALLOWED_ORIGINS","").split(","))if(!allowed.isBlank())origins.add(allowed.trim());
        ExecutorService executor=Executors.newFixedThreadPool(8);
        Runtime.getRuntime().addShutdownHook(new Thread(()->{server.stop(1);executor.shutdownNow();store.close();}));
        server.createContext("/api/",x->{try{String path=x.getRequestURI().getPath();Map<String,Object>u=user(x);x.getResponseHeaders().set("Cache-Control","no-store");if(x.getRequestMethod().equals("GET")&&path.equals("/api/config")){respond(x,200,Map.of("demoMode",Boolean.parseBoolean(Config.get("SEED_DEMO_DATA","true"))&&!Boolean.parseBoolean(Config.get("COOKIE_SECURE","false"))));return;}if(x.getRequestMethod().equals("GET")&&path.equals("/api/health")){store.healthCheck();respond(x,200,Map.of("status","ok","database","connected"));return;}if(x.getRequestMethod().equals("GET")&&path.equals("/api/state")){if(u==null){respond(x,401,Map.of("error","Please sign in."));return;}respond(x,200,store.view(u));return;}if(!x.getRequestMethod().equals("POST")){respond(x,405,Map.of("error","Method not allowed."));return;}String origin=x.getRequestHeaders().getFirst("Origin");if(origin!=null&&!origins.contains(origin)){respond(x,403,Map.of("error","Origin rejected."));return;}Map<String,Object>m=body(x);switch(path){case "/api/login"->{Map<String,Object>who=store.login(m);String token=UUID.randomUUID().toString()+UUID.randomUUID();sessions.put(token,new Session(who,System.currentTimeMillis()+8*60*60*1000));x.getResponseHeaders().add("Set-Cookie","session="+token+"; HttpOnly; SameSite=Strict; Path=/; Max-Age=28800"+secure);respond(x,200,who);}case "/api/logout"->{String cookies=Objects.toString(x.getRequestHeaders().getFirst("Cookie"),"");for(String c:cookies.split(";"))if(c.trim().startsWith("session="))sessions.remove(c.trim().substring(8));x.getResponseHeaders().add("Set-Cookie","session=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0"+secure);respond(x,200,Map.of("ok",true));}case "/api/quote"->{if(u==null){respond(x,401,Map.of("error","Please sign in."));return;}respond(x,200,store.quote(m));}case "/api/action"->{if(u==null&&!"register".equals(m.get("op"))){respond(x,401,Map.of("error","Please sign in."));return;}respond(x,200,store.mutate(m,u));}default->respond(x,404,Map.of("error","Not found."));}}catch(IllegalArgumentException|NullPointerException|IndexOutOfBoundsException e){respond(x,400,Map.of("error",Objects.toString(e.getMessage(),"Please check the submitted fields.")));}catch(Persistence.ConflictException e){respond(x,409,Map.of("error",e.getMessage()));}catch(java.sql.SQLException e){System.err.println("MySQL operation failed: "+e.getClass().getSimpleName());respond(x,503,Map.of("error","Database is temporarily unavailable. Please try again."));}catch(Exception e){System.err.println("Operation failed: "+e.getClass().getSimpleName());respond(x,500,Map.of("error","Unable to save your changes. Please try again."));}});
        server.createContext("/",x->{try{if(!x.getRequestMethod().equals("GET")){x.sendResponseHeaders(405,-1);x.close();return;}Path root=Path.of("public").toAbsolutePath();String path=x.getRequestURI().getPath();Path f=root.resolve(path.equals("/")?"index.html":path.substring(1)).normalize();if(!f.startsWith(root)||!Files.isRegularFile(f)){x.sendResponseHeaders(404,-1);x.close();return;}String type=f.toString().endsWith(".css")?"text/css":f.toString().endsWith(".js")?"application/javascript":"text/html";x.getResponseHeaders().set("Content-Type",type+"; charset=utf-8");x.getResponseHeaders().set("X-Content-Type-Options","nosniff");x.getResponseHeaders().set("Content-Security-Policy","default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self'; img-src 'self' data:; object-src 'none'; frame-ancestors 'none'");byte[]b=Files.readAllBytes(f);x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();}catch(Exception e){x.close();}});
        server.setExecutor(executor);server.start();System.out.println("Parcelly is running at http://localhost:"+port+" (MySQL database: "+Config.database()+")");
    }
}
